#[test]
fn unit_metadata() {
    let info = Irradiation::<f64>::INFO;
    assert_eq!(info.name, "Irradiation");
    assert_eq!(info.units.len(), IrradiationUnit::ALL.len());
    for (&unit, unit_info) in IrradiationUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, IrradiationUnit::JoulePerSquareMeter.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        Irradiation::new(v, IrradiationUnit::JoulePerSquareMeter),
        Irradiation::from_joules_per_square_meter(v)
    );
    assert_eq!(
        Irradiation::from_base(v).convert_to(IrradiationUnit::JoulePerSquareMeter),
        Irradiation::from_base(v).as_joules_per_square_meter()
    );
    assert_eq!(
        Irradiation::new(v, IrradiationUnit::KilojoulePerSquareMeter),
        Irradiation::from_kilojoules_per_square_meter(v)
    );
    assert_eq!(
        Irradiation::from_base(v).convert_to(IrradiationUnit::KilojoulePerSquareMeter),
        Irradiation::from_base(v).as_kilojoules_per_square_meter()
    );
    assert_eq!(
        Irradiation::new(v, IrradiationUnit::JoulePerSquareCentimeter),
        Irradiation::from_joules_per_square_centimeter(v)
    );
    assert_eq!(
        Irradiation::from_base(v).convert_to(IrradiationUnit::JoulePerSquareCentimeter),
        Irradiation::from_base(v).as_joules_per_square_centimeter()
    );
    assert_eq!(
        Irradiation::new(v, IrradiationUnit::MillijoulePerSquareCentimeter),
        Irradiation::from_millijoules_per_square_centimeter(v)
    );
    assert_eq!(
        Irradiation::from_base(v).convert_to(IrradiationUnit::MillijoulePerSquareCentimeter),
        Irradiation::from_base(v).as_millijoules_per_square_centimeter()
    );
    assert_eq!(
        Irradiation::new(v, IrradiationUnit::JoulePerSquareMillimeter),
        Irradiation::from_joules_per_square_millimeter(v)
    );
    assert_eq!(
        Irradiation::from_base(v).convert_to(IrradiationUnit::JoulePerSquareMillimeter),
        Irradiation::from_base(v).as_joules_per_square_millimeter()
    );
    assert_eq!(
        Irradiation::new(v, IrradiationUnit::WattHourPerSquareMeter),
        Irradiation::from_watt_hours_per_square_meter(v)
    );
    assert_eq!(
        Irradiation::from_base(v).convert_to(IrradiationUnit::WattHourPerSquareMeter),
        Irradiation::from_base(v).as_watt_hours_per_square_meter()
    );
    assert_eq!(
        Irradiation::new(v, IrradiationUnit::KilowattHourPerSquareMeter),
        Irradiation::from_kilowatt_hours_per_square_meter(v)
    );
    assert_eq!(
        Irradiation::from_base(v).convert_to(IrradiationUnit::KilowattHourPerSquareMeter),
        Irradiation::from_base(v).as_kilowatt_hours_per_square_meter()
    );
    assert_eq!(
        Irradiation::new(v, IrradiationUnit::BtuPerSquareFoot),
        Irradiation::from_btus_per_square_foot(v)
    );
    assert_eq!(
        Irradiation::from_base(v).convert_to(IrradiationUnit::BtuPerSquareFoot),
        Irradiation::from_base(v).as_btus_per_square_foot()
    );
    assert_eq!(
        Irradiation::new(v, IrradiationUnit::KilobtuPerSquareFoot),
        Irradiation::from_kilobtus_per_square_foot(v)
    );
    assert_eq!(
        Irradiation::from_base(v).convert_to(IrradiationUnit::KilobtuPerSquareFoot),
        Irradiation::from_base(v).as_kilobtus_per_square_foot()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Irradiation; 9] = [
        Irradiation::const_new(1234.5, IrradiationUnit::JoulePerSquareMeter),
        Irradiation::const_new(1234.5, IrradiationUnit::KilojoulePerSquareMeter),
        Irradiation::const_new(1234.5, IrradiationUnit::JoulePerSquareCentimeter),
        Irradiation::const_new(1234.5, IrradiationUnit::MillijoulePerSquareCentimeter),
        Irradiation::const_new(1234.5, IrradiationUnit::JoulePerSquareMillimeter),
        Irradiation::const_new(1234.5, IrradiationUnit::WattHourPerSquareMeter),
        Irradiation::const_new(1234.5, IrradiationUnit::KilowattHourPerSquareMeter),
        Irradiation::const_new(1234.5, IrradiationUnit::BtuPerSquareFoot),
        Irradiation::const_new(1234.5, IrradiationUnit::KilobtuPerSquareFoot),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(IrradiationUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Irradiation::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in IrradiationUnit::ALL {
            assert_eq!(
                Irradiation::const_new(v, unit).as_base().to_bits(),
                Irradiation::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Irradiation::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            Irradiation::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in IrradiationUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Irradiation::from_base(0.0).auto_unit().unit,
        IrradiationUnit::JoulePerSquareMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "J/m²".parse::<IrradiationUnit>(),
        Ok(IrradiationUnit::JoulePerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "J/m²").parse::<Irradiation>(),
        Ok(Irradiation::new(2.5, IrradiationUnit::JoulePerSquareMeter))
    );
    assert_eq!(
        "kJ/m²".parse::<IrradiationUnit>(),
        Ok(IrradiationUnit::KilojoulePerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "kJ/m²").parse::<Irradiation>(),
        Ok(Irradiation::new(
            2.5,
            IrradiationUnit::KilojoulePerSquareMeter
        ))
    );
    assert_eq!(
        "J/cm²".parse::<IrradiationUnit>(),
        Ok(IrradiationUnit::JoulePerSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "J/cm²").parse::<Irradiation>(),
        Ok(Irradiation::new(
            2.5,
            IrradiationUnit::JoulePerSquareCentimeter
        ))
    );
    assert_eq!(
        "mJ/cm²".parse::<IrradiationUnit>(),
        Ok(IrradiationUnit::MillijoulePerSquareCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "mJ/cm²").parse::<Irradiation>(),
        Ok(Irradiation::new(
            2.5,
            IrradiationUnit::MillijoulePerSquareCentimeter
        ))
    );
    assert_eq!(
        "J/mm²".parse::<IrradiationUnit>(),
        Ok(IrradiationUnit::JoulePerSquareMillimeter)
    );
    assert_eq!(
        format!("2.5 {}", "J/mm²").parse::<Irradiation>(),
        Ok(Irradiation::new(
            2.5,
            IrradiationUnit::JoulePerSquareMillimeter
        ))
    );
    assert_eq!(
        "Wh/m²".parse::<IrradiationUnit>(),
        Ok(IrradiationUnit::WattHourPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "Wh/m²").parse::<Irradiation>(),
        Ok(Irradiation::new(
            2.5,
            IrradiationUnit::WattHourPerSquareMeter
        ))
    );
    assert_eq!(
        "kWh/m²".parse::<IrradiationUnit>(),
        Ok(IrradiationUnit::KilowattHourPerSquareMeter)
    );
    assert_eq!(
        format!("2.5 {}", "kWh/m²").parse::<Irradiation>(),
        Ok(Irradiation::new(
            2.5,
            IrradiationUnit::KilowattHourPerSquareMeter
        ))
    );
    assert_eq!(
        "Btu/ft²".parse::<IrradiationUnit>(),
        Ok(IrradiationUnit::BtuPerSquareFoot)
    );
    assert_eq!(
        format!("2.5 {}", "Btu/ft²").parse::<Irradiation>(),
        Ok(Irradiation::new(2.5, IrradiationUnit::BtuPerSquareFoot))
    );
    assert_eq!(
        "kBtu/ft²".parse::<IrradiationUnit>(),
        Ok(IrradiationUnit::KilobtuPerSquareFoot)
    );
    assert_eq!(
        format!("2.5 {}", "kBtu/ft²").parse::<Irradiation>(),
        Ok(Irradiation::new(2.5, IrradiationUnit::KilobtuPerSquareFoot))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Irradiation>(),
        Err(ParseError::UnknownUnit)
    );
}

